const KEY_ACTIONS = new Map([
  ['ArrowLeft', 'left'], ['ArrowRight', 'right'], ['ArrowDown', 'down'], ['ArrowUp', 'rotate'],
  [' ', 'drop'], ['Spacebar', 'drop'], ['c', 'hold'], ['C', 'hold'], ['Shift', 'hold'],
  ['Escape', 'pause'], ['p', 'pause'], ['P', 'pause'],
]);
export function actionForKey(key){return KEY_ACTIONS.get(key)??null;}
export function bindKeyboard(handleAction,target=globalThis.window){if(!target?.addEventListener)return()=>{};const listener=(event)=>{const action=actionForKey(event.key);if(!action)return;event.preventDefault();handleAction(action);};target.addEventListener('keydown',listener,{passive:false});return()=>target.removeEventListener('keydown',listener);}
export function bindTouchControls(root,handleAction){if(!root?.querySelectorAll)return()=>{};const cleanups=[];const repeatable=new Set(['left','right','down']);root.querySelectorAll('[data-action]').forEach((button)=>{const action=button.dataset.action;let repeatDelay=null,repeatTimer=null;const clearTimers=()=>{if(repeatDelay)clearTimeout(repeatDelay);if(repeatTimer)clearInterval(repeatTimer);repeatDelay=null;repeatTimer=null;};const start=(event)=>{event.preventDefault();button.setPointerCapture?.(event.pointerId);handleAction(action);if(repeatable.has(action)){repeatDelay=setTimeout(()=>{repeatTimer=setInterval(()=>handleAction(action),action==='down'?55:80);},190);}};const end=(event)=>{event.preventDefault();clearTimers();};button.addEventListener('pointerdown',start,{passive:false});button.addEventListener('pointerup',end,{passive:false});button.addEventListener('pointercancel',end,{passive:false});button.addEventListener('pointerleave',clearTimers);button.addEventListener('contextmenu',(event)=>event.preventDefault());cleanups.push(()=>{clearTimers();button.removeEventListener('pointerdown',start);button.removeEventListener('pointerup',end);button.removeEventListener('pointercancel',end);button.removeEventListener('pointerleave',clearTimers);});});return()=>cleanups.forEach((cleanup)=>cleanup());}
